window.SKIM_PAPERS["2209.15189"] = {"concepts": [{"id": "context-distillation", "name": "Context distillation", "tier": "minor", "parent": null, "summary": "A model is prompted with an informative context, samples its own completions, and is then finetuned to reproduce those completions from a shorter prompt with the context removed. The effect of the context ends up in the weights instead of in the prompt.", "explanation": "Ordinary knowledge distillation starts from two different models: a teacher with parameters theta_TEACHER and a student theta_STUDENT, and the training signal comes from the gap between them. Context distillation starts with theta_TEACHER = theta_STUDENT — one model playing both roles — and the training signal comes instead from a difference in what the two roles are shown and asked to predict. The loop is: sample a raw task input x from a distribution D; build the teacher's prompt T_TEACHER(x), which carries detailed instructions, explanations or in-context examples; sample a completion y from P_theta_TEACHER(. | T_TEACHER(x)); extract the final answer f(y) from that completion; then finetune the student to predict f(y) from a shorter prompt T_STUDENT(x). Formally the objective maximized is L(theta_STUDENT) = E_{x ~ D} [ E_{y ~ P_theta_TEACHER(. | T_TEACHER(x))} [ log P_theta_STUDENT( f(y) | T_STUDENT(x) ) ] ], with theta_TEACHER held fixed throughout, so the student is chasing a stationary target even though it began as a copy of it. No human labels are involved anywhere: the only inputs needed are unlabeled x's, which can be rule-generated strings, drawn from a pool of unlabeled data, or sampled from the model itself by few-shot prompting. The paper's stated motivations are that context tokens cost inference compute (its students used 8 to 11.1 times fewer tokens than their teachers) and that a context longer than the window cannot be used at all. The paper notes that the earlier method others called context distillation or prompt injection — distilling one fixed prompt — is the special case where the student template is the identity and the answer extractor is the identity. A caveat the paper states directly: the teacher's performance is generally an upper bound on the student's, so the method internalizes at best what prompting already elicits.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Sections 2.1 and 2.2, Equation 1; Figure 1; related-work discussion of prompt injection in Section 4", "ownerPaper": "2209.15189", "sources": {"paperId": "2209.15189", "note": "Sections 2.1 and 2.2, Equation 1; Figure 1; related-work discussion of prompt injection in Section 4", "sections": [], "pages": []}}, {"id": "distillation-components", "name": "The four components: input distribution, teacher template, student template, answer extractor", "tier": "minor", "parent": null, "summary": "Setting up a context distillation run means choosing four things: where raw inputs come from, the long prompt, the short prompt, and how the final answer is cut out of the teacher's generation. The gap between the two templates is exactly what gets moved into the weights.", "explanation": "D is a distribution over raw task inputs — the 'core' input of the task, kept distinct from the full prompt. The paper generates D three ways depending on the experiment: by rule (uniform over all 1- to 8-digit addition expressions), from an existing pool of unlabeled data, or, most often, by few-shot prompting the same model to write more inputs of the right kind (for instance, prompting it to write movie reviews when the task is sentiment classification). T_TEACHER maps a raw input to the long prompt: a task description, positive and negative in-context examples, natural-language explanations of why an output is right or wrong, a database schema, or a stated fact. T_STUDENT maps the same raw input to a shorter prompt; the paper says it should still carry enough that the request is not underspecified, but with far fewer explanations and examples, and that this difference is what transfers the context into the parameters. In the extreme the student template is the identity map, so the student sees only the bare input and must have absorbed the task description entirely. f maps token sequences to token sequences, pulling the final answer out of the teacher's full generation; it strips away an intermediate scratchpad when there is one, and is simply the identity when the teacher's output is already the answer. Because f is applied after sampling, the student never sees the reasoning the teacher did, only what that reasoning produced — the paper's framing is that the student has to internalize the reasoning in order to predict the endpoint directly.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 2.1 (component definitions); Figures 2, 3 and 4 show concrete teacher/student template pairs", "ownerPaper": "2209.15189", "sources": {"paperId": "2209.15189", "note": "Section 2.1 (component definitions); Figures 2, 3 and 4 show concrete teacher/student template pairs", "sections": [], "pages": []}}, {"id": "what-context-distillation-transfers", "name": "What context distillation is shown to transfer", "tier": "minor", "parent": null, "summary": "The paper reports that three kinds of context transfer into weights — abstract task instructions, natural-language explanations, and step-by-step reasoning skill — and that a distilled skill can show up on differently-worded tasks it was never distilled on.", "explanation": "Abstract instructions: on ten held-out tasks from Natural-Instructions-V2 (a collection of 1600+ tasks each carrying a description, in-context examples and explanations), the teacher prompted with the full instruction scored 43.4 Rouge-L; the student, shown only the bare input, scored 9.0 before distillation and 34.7 after — most of the gap, not all of it, with 11.1 times fewer inference tokens. Explanations: comparing an 'in-context margin' (how much adding explanations helps the teacher) against a 'distillation margin' (how much the student gains) across those tasks, the paper reports a positive correlation of r = 0.75 at p = 1%, and says plainly that not all tasks benefit. Concrete examples: on the SPIDER text-to-SQL dataset with Incoder-6.7B, distilling four in-context examples took the student from 0.3 to 22.1 exact set match against 13.4 for finetuning directly on the same four examples by gradient descent, a gap the paper reports widening slightly at eight examples (27.9 versus 18.9). Reasoning: distilling scratchpad addition into T5-small moved direct 8-digit addition from 0% to 94.7%, versus 72% and 61% for transfer-learning and multi-task baselines on the same data. The transfer result matters most for anyone borrowing the method: distilling bare addition scratchpads into an instruction-tuned model lifted its direct addition from 1% to 17%, and also lifted its accuracy on templated word problems ('A has 7 turkeys. B has 2 turkeys. How many altogether?') from 17% to 30% — a differently-formatted task that was never in the distillation data. Side effects were checked only coarsely and only for capability loss: general Natural-Instructions Rouge-L went 57 to 58, and 65536 instruction examples were mixed into the distillation data specifically to prevent catastrophic forgetting. A separate result shows the student can absorb something other than the intended contents of the context: when each task's raw inputs were drawn only from that task's own distribution, a student trained to associate a numeric task id with a task instead keyed off the input distribution, scoring 68 on correct ids but also 61 on wrong ids; mixing all input distributions together fixed this (70 correct, 16 wrong).", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Sections 3.1, 3.2 and 3.3 (Hypotheses 1-7); Tables 1, 2 and 3; Figure 5; per-task detail in Appendix Table 6", "ownerPaper": "2209.15189", "sources": {"paperId": "2209.15189", "note": "Sections 3.1, 3.2 and 3.3 (Hypotheses 1-7); Tables 1, 2 and 3; Figure 5; per-task detail in Appendix Table 6", "sections": [], "pages": []}}, {"id": "distilling-behavioral-instructions", "name": "Distilling behavioral instructions and stated facts", "tier": "minor", "parent": null, "summary": "Beyond task skills, the paper distills prompts that describe how the model should behave or what it should believe, and reports that the behavior persists once the prompt is gone. It also reports that the change can spread past its intended scope.", "explanation": "In a controlled-generation experiment, the teacher template asked the instruction-tuned model to complete a negative IMDB movie review so that it ends on a positive note, while the student template asked only to complete the review with no such specification. After distillation the student produced more positive text unprompted, judged by asking GPT-3 whether each generation was positive, with output coherence (measured by Rouge-L) and output diversity (measured by output entropy in nats) not much changed. In a fact-editing experiment on the Counterfact dataset, the teacher template stated an edited fact together with an instruction not to change unrelated facts, plus demonstrations and explanations covering paraphrases, neighborhood cases and attribute cases; the student was then finetuned to behave accordingly without the statement. Counterfact scores the edit two ways: paraphrase prompts, where the new fact should carry over, and neighborhood prompts, where unrelated facts sharing the old object should not move. The student went from 34 to 79 on paraphrase score, matching or beating the teacher's 73, but fell from 80 to 48 on neighborhood score against the teacher's 58. So the edit generalized to rewordings it was never trained on, and also leaked into facts it was explicitly instructed to leave alone; the paper attributes the leakage to its own teacher's weak neighborhood behavior and expects larger models to do better, citing GPT-3's stronger neighborhood score under the same prompt as indirect support. These are appendix experiments on a single 11B instruction-tuned model, and the paper presents them as demonstrations of reach rather than as competitive results — it says explicitly that its fact-editing numbers are not directly comparable to dedicated editing methods because it spends far more compute.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Appendix A.1 (controlled generation, Table 4) and Appendix A.2 (fact editing, Table 5)", "ownerPaper": "2209.15189", "sources": {"paperId": "2209.15189", "note": "Appendix A.1 (controlled generation, Table 4) and Appendix A.2 (fact editing, Table 5)", "sections": [], "pages": []}}, {"id": "soft-label-objective", "name": "Token-level KL versus hard-label finetuning", "tier": "minor", "parent": null, "summary": "The straightforward way to run the method is to sample the teacher's output and finetune on those tokens as hard labels; the paper instead matches the teacher's per-token distribution, approximated from 100 sampled tokens per position.", "explanation": "The paper calls sampling y and finetuning on the hard label f(y) the naive way to optimize its objective, on the grounds that it discards the teacher's token logits and gives noisy gradients. Its own implementation minimizes the token-level KL divergence between the student's and teacher's next-token distributions instead. Storing full soft labels is expensive because language model vocabularies run to roughly 50,000-100,000 entries, so the teacher distribution at each position is approximated by the empirical distribution of 100 sampled tokens — described as saving substantial memory while still working well enough. This is an implementation choice about gradient quality rather than a different method: the hard-label version is the same objective, Equation 1, estimated with a single sample. Anyone reusing the recipe by generating text under a prompt and finetuning on that text is therefore running the naive variant the paper describes and improves on, not something outside its framework. The standard settings for the reported runs were 4096 distillation examples for 1 epoch at batch size 16 with AdamW, learning rate 1e-5 for the T5-based instruction-tuned model and 1e-4 for the code model, zero weight decay; the transfer experiment instead used 10k distillation examples for 3 epochs mixed with 65536 instruction-tuning examples.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 2.4 (implementation details); hyperparameters in Appendix B.3 and B.6", "ownerPaper": "2209.15189", "sources": {"paperId": "2209.15189", "note": "Section 2.4 (implementation details); hyperparameters in Appendix B.3 and B.6", "sections": [], "pages": []}}], "items": [], "edges": [], "themes": [], "pages": [], "narrative": null, "insights": null, "summary": null, "reading": [], "refs": {"accessed": []}, "regions": [], "pdfPages": 0, "readerKind": "pdf", "sections": []};
